const startedAt = Number(v2TurnStartAt.get(sid));
const hasTurn = Number.isFinite(startedAt) && startedAt > 0;
const collector = collectors.has(sid);
if (!hasTurn) return false;
// [LOCAL-HOOK turn-guard] 回合静默判死：起头之后长时间没有任何事件，说明 DSH 那边这个回合已经死了
// （2026-10-31 实测：她那条会话日志停在 step/start，DSH 侧 stopSessionWork 返回 removed:0）。
// turn/end 永不到来，新消息就只能一直排队，表现成「卡住不回」。
const idleLimit = Number(cfg.socialV2?.turnIdleMs) > 0 ? Number(cfg.socialV2.turnIdleMs) : 180000;
const lastEventAt = Number(v2TurnLastEventAt.get(sid)) || startedAt;
const idleFor = Date.now() - Math.max(startedAt, lastEventAt);
const queuedReasons = Array.isArray(st?.pendingWakeReasons) ? st.pendingWakeReasons.length : 0;
if (queuedReasons > 0 && idleFor >= idleLimit) {
  v2TurnStartAt.delete(sid);
  v2TurnLastEventAt.delete(sid);
  turnLeaseNoted.delete(sid);
  st.pendingWakeReasons = [];
  log(`[本地补丁][判死] 回合 ${Math.round(idleFor / 1000)}s 没有任何事件、且有 ${queuedReasons} 条消息在排队，判定已死并解除忙碌（${sid}）`);
  return false;
}
if (Date.now() - startedAt < TURN_BUSY_LEASE_MS) return true;

// [LOCAL-HOOK approval-silent] QQ 会话是无人值守：审批一律静默放行，
// 不再往 QQ 发「🔐 agent 请求审批」（那条消息最像机器人，而且没人回就会卡住 5 分钟）。
try {
  await withTimeout(api.respond({ clientId: frame.clientId, eventId: frame.eventId, outcome: { kind: 'result', value: 'allowed-once' } }), 5000, '静默放行审批');
  log(`[本地补丁][审批] 静默放行 ${key}：${frame.toolName || '(未知工具)'}`);
} catch (error) {
  log(`[本地补丁][审批] 放行失败 ${key}：${error?.message ?? error}`);
}
continue;

