    // 短醒不能只靠外部消息触发：被睡眠挡回去时，按「还有多久到短醒」给自己排一次自发醒来
    const napIn = Number(gate.napInMs) || 0;
    const timerDriven = ['proactiveCheck', 'groupListen', 'timeout', 'replyCheck', 'bootstrap'].includes(String(reason));
    const napSlotBusy = customNapWakeKey && customNapWakeKey !== key && customNapWakeAt > Date.now() - 30000;
    if (timerDriven && !napSlotBusy && napIn > 3000 && napIn < 3 * 60 * 60 * 1000) {
      const dueAt = Date.now() + napIn + 3000;
      const prev = Number(stForGuard.napWakeAt || 0);
      if (!(prev > Date.now() - 120000 && Math.abs(prev - dueAt) < 120000)) {
        stForGuard.napWakeAt = dueAt;
        customNapWakeKey = key;
        customNapWakeAt = dueAt;
        const napTimer = setTimeout(() => {
          stForGuard.napWakeAt = 0;
          if (customNapWakeKey === key) { customNapWakeKey = ''; customNapWakeAt = 0; }
          sendWakePromptV2(key, 'proactiveCheck').catch((error) => log(`[作息] 短醒自发唤醒失败 ${key}：${String(error?.message ?? error).slice(0, 120)}`));
        }, napIn + 3000);
        if (typeof napTimer.unref === 'function') napTimer.unref();
        log(`[作息] ${key} 的短醒还有 ${Math.round(napIn / 60000)} 分钟，已安排自己醒一次`);
      }
    }
