    const cur = JSON.parse(fs.readFileSync(path.join(home, '.dsh', 'surfcore', 'characters', 'current.json'), 'utf8'));
    const id = String(cur?.id ?? '').trim();
    if (id) return path.join(home, '.dsh', 'surfcore', 'characters', id, 'bili');
  } catch {}
  return '';
