// [LOCAL-HOOK bili/dual-dir] name → 实际要读的文件：角色包优先，没有再回退旧全局目录。
// 为什么不是只读角色包：老数据和测试夹具都写在全局目录，只读角色包会让上游 test:bili 挂。
function biliDataFile(name) {
  const a = paths.biliChar ? path.join(paths.biliChar, name) : '';
  if (a && fs.existsSync(a)) return a;
  return path.join(paths.bili, name);
}

